function renderImage(word){
  const src=word.image&&word.image.src;

  if(!src){
    wordIllustration.hidden=true;
    wordImage.removeAttribute("src");
    wordImage.alt="";
    return;
  }

  wordIllustration.hidden=false;
  wordImage.alt=word.translations[activeLocale]||word.translations.ru||"";
  wordImage.onerror=()=>{
    wordIllustration.hidden=true;
    wordImage.removeAttribute("src");
  };
  wordImage.src=src;
}
