function getOrderedUnderstandChoices(item){const choices=Array.isArray(item.choices)?item.choices:[];if(!choices.length)return[];const offset=[...item.id].reduce((total,character)=>total+character.charCodeAt(0),0)%choices.length;return choices.slice(offset).concat(choices.slice(0,offset));}
function renderUnderstandChoice(item){const choices=getOrderedUnderstandChoices(item),isCurrentItem=understandChoiceItemId===item.id;understandChoice.hidden=false;understandChoiceInstruction.textContent=t("understandChoiceInstruction");understandChoiceOptions.innerHTML="";choices.forEach((choice)=>{const selected=isCurrentItem&&understandChoiceSelectionId===choice.id,isCorrect=selected&&understandChoiceResult==="correct",isIncorrect=selected&&understandChoiceResult==="incorrect",button=document.createElement("button");button.type="button";button.className=`understand-choice-option${isCorrect?" is-correct":""}${isIncorrect?" is-incorrect":""}`;button.lang="ar";button.dir="rtl";button.textContent=choice.arabic;button.setAttribute("aria-pressed",String(selected));if(selected)button.setAttribute("aria-label",`${choice.arabic}. ${t(isCorrect?"understandChoiceSelectedCorrect":"understandChoiceSelectedWrong")}`);button.disabled=isCurrentItem&&understandChoiceResult==="correct";button.addEventListener("click",()=>selectUnderstandChoice(item,choice));understandChoiceOptions.appendChild(button);});const isCorrect=isCurrentItem&&understandChoiceResult==="correct";understandChoiceHelp.textContent=t("understandChoiceHelp");understandChoiceHelp.hidden=isCorrect;understandChoiceHelp.disabled=understandChoiceHelpLevel>=2;understandChoiceHelp.onclick=()=>requestUnderstandChoiceHelp(item);understandChoiceFeedback.className=`understand-choice-feedback${isCorrect?" is-correct":""}`;understandChoiceFeedback.textContent=!isCurrentItem?"":t(isCorrect?"understandChoiceCorrect":"understandChoiceWrong");understandChoiceAnswer.hidden=!isCorrect;understandChoiceAnswer.textContent=isCorrect?item.answerTranslations[activeLocale]||item.answerTranslations.ru||"":"";}
function renderUnderstandProgressiveHelp(level){understandQuestionArabic.hidden=level<1;understandQuestionMeaning.hidden=level<2;}
function requestUnderstandChoiceHelp(item){if(understandChoiceResult==="correct"||understandChoiceHelpLevel>=2)return;understandChoiceHelpLevel+=1;renderUnderstandProgressiveHelp(understandChoiceHelpLevel);renderUnderstandChoice(item);}
function selectUnderstandChoice(item,choice){if(!choice||understandChoiceItemId===item.id&&understandChoiceResult==="correct")return;understandChoiceItemId=item.id;understandChoiceSelectionId=choice.id;understandChoiceResult=choice.correct?"correct":"incorrect";renderUnderstandChoice(item);}
function renderUnderstandStage(lesson,position){const items=lesson.understand||[],item=items[position],mode=getUnderstandMode(lesson),isChoice=mode==="listenChoice";$("understand-stage-kicker").textContent=t("understandStageKicker");understandPosition.textContent=t("understandPosition",{current:position+1,total:items.length});$("understand-question-label").textContent=t("understandQuestionLabel");understandModeRead.textContent=t("understandModeRead");understandModeArabic.textContent=t("understandModeArabic");understandModeChoice.textContent=t("understandModeChoice");$(".understand-mode").setAttribute("aria-label",t("understandModeLabel"));understandModeRead.setAttribute("aria-pressed",String(mode==="listenRead"));understandModeArabic.setAttribute("aria-pressed",String(mode==="listenArabic"));understandModeChoice.setAttribute("aria-pressed",String(isChoice));understandQuestionArabic.textContent=item.questionArabic;understandQuestionMeaning.textContent=item.questionTranslations[activeLocale]||item.questionTranslations.ru||"";if(isChoice)renderUnderstandProgressiveHelp(understandChoiceHelpLevel);else{understandQuestionArabic.hidden=false;understandQuestionMeaning.hidden=mode==="listenArabic";}renderUnderstandAudio(item);$("understand-answer-label").textContent=t("understandAnswerLabel");understandAnswerArabic.textContent=item.answerArabic;understandAnswerMeaning.textContent=item.answerTranslations[activeLocale]||item.answerTranslations.ru||"";understandAnswerPart.hidden=isChoice;understandAnswerPart.style.display=isChoice?"none":"";if(isChoice)renderUnderstandChoice(item);else understandChoice.hidden=true;understandPrevious.textContent=t("understandPrevious");understandNext.textContent=t("understandNext");understandPrevious.disabled=position===0;understandNext.disabled=position===items.length-1;wordCard.hidden=true;speakStageShell.hidden=true;expandStageShell.hidden=true;builderCard.hidden=true;$("learning-actions").hidden=true;understandStageShell.hidden=false;}
function getOrderedUnderstandBuildChunks(item){const chunks=item.build&&Array.isArray(item.build.chunks)?item.build.chunks:[];if(!chunks.length)return[];const offset=[...(item.id+"-build")].reduce((total,character)=>total+character.charCodeAt(0),0)%chunks.length;return chunks.slice(offset).concat(chunks.slice(0,offset));}
function renderUnderstandBuild(item){const build=item.build,isCurrent=understandBuildItemId===item.id;if(!build){understandBuildInstruction.textContent=t("understandBuildUnavailable");understandBuildHelp.hidden=true;understandBuildAnswer.innerHTML="";understandBuildOptions.innerHTML="";understandBuildFeedback.textContent="";understandBuildMeaning.hidden=true;understandBuildCheck.hidden=true;return;}const selected=isCurrent?understandBuildSelectionIds:[],byId=new Map(build.chunks.map(chunk=>[chunk.id,chunk])),isCorrect=isCurrent&&understandBuildResult==="correct";understandBuildInstruction.textContent=t("understandBuildInstruction");understandBuildHelp.textContent=t("understandChoiceHelp");understandBuildHelp.hidden=isCorrect;understandBuildHelp.disabled=understandBuildHelpLevel>=2;understandBuildHelp.onclick=()=>requestUnderstandBuildHelp(item);understandBuildAnswer.innerHTML="";selected.forEach(id=>{const chunk=byId.get(id);if(!chunk)return;const button=document.createElement("button");button.type="button";button.className="understand-build-chunk";button.lang="ar";button.dir="rtl";button.textContent=chunk.arabic;button.disabled=isCorrect;button.addEventListener("click",()=>removeUnderstandBuildChunk(item,id));understandBuildAnswer.appendChild(button);});understandBuildOptions.innerHTML="";getOrderedUnderstandBuildChunks(item).filter(chunk=>!selected.includes(chunk.id)).forEach(chunk=>{const button=document.createElement("button");button.type="button";button.className="understand-build-chunk";button.lang="ar";button.dir="rtl";button.textContent=chunk.arabic;button.disabled=isCorrect;button.addEventListener("click",()=>selectUnderstandBuildChunk(item,chunk.id));understandBuildOptions.appendChild(button);});understandBuildFeedback.className=`understand-build-feedback${isCorrect?" is-success":""}`;understandBuildFeedback.textContent=!isCurrent||!understandBuildResult?"":t(isCorrect?"understandBuildCorrect":"understandBuildWrong");understandBuildMeaning.hidden=!isCorrect;understandBuildMeaning.textContent=isCorrect?item.answerTranslations[activeLocale]||item.answerTranslations.ru||"":"";understandBuildCheck.hidden=false;understandBuildCheck.textContent=t("understandBuildCheck");understandBuildCheck.disabled=isCorrect||!selected.length;}
function selectUnderstandBuildChunk(item,id){if(understandBuildItemId===item.id&&understandBuildResult==="correct")return;understandBuildItemId=item.id;understandBuildSelectionIds=understandBuildItemId===item.id?[...understandBuildSelectionIds,id]:[id];understandBuildResult="";renderUnderstandBuild(item);}
function removeUnderstandBuildChunk(item,id){if(understandBuildItemId!==item.id||understandBuildResult==="correct")return;understandBuildSelectionIds=understandBuildSelectionIds.filter(selectedId=>selectedId!==id);understandBuildResult="";renderUnderstandBuild(item);}
function checkUnderstandBuild(){const lesson=getCurrentLesson(),item=(lesson.understand||[])[getUnderstandPosition(lesson)],build=item&&item.build;if(!build||understandBuildItemId!==item.id||!understandBuildSelectionIds.length)return;understandBuildResult=understandBuildSelectionIds.length===build.answerChunkIds.length&&understandBuildSelectionIds.every((id,index)=>id===build.answerChunkIds[index])?"correct":"incorrect";renderUnderstandBuild(item);}
function requestUnderstandBuildHelp(item){if(understandBuildResult==="correct"||understandBuildHelpLevel>=2)return;understandBuildHelpLevel+=1;renderUnderstandProgressiveHelp(understandBuildHelpLevel);renderUnderstandBuild(item);}
understandBuildCheck.addEventListener("click",checkUnderstandBuild);
